{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.cut_size_cogs as WITH base_wh_data AS ( SELECT UPPER(TRIM(\"Item SkuCode\")) AS sku_item, TRIM(REGEXP_REPLACE(UPPER(TRIM(\"Item SkuCode\")), \'-[^-]*$\', \'\')) AS parent_style, \"Category Name\", SUM(\"INVENTORY\") AS \"Available\", SUM(\"Inventory Blocked\") AS \"Blocked\", SUM(TRY_TO_NUMBER(\"Not Found\")) AS \"Not Found\", SUM(\"Putaway Pending\") AS \"Putaway Pending\", SUM(\"Putback Pending\") AS \"Putback Pending\", SUM(\"Bad Inventory\") AS \"Bad Inventory\", SUM(\"Inventory Not Synced\") AS \"Not Synced\", SUM(\"Stock In Transfer\") AS \"Stock Transfer\" FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE \"FACILITY\" IN (\'SAPL_EMIZA\', \'SAPL-WH1\', \'SAPL-WH2\', \'SAPL-NORTH-TAURU\') AND \"DATE\" = CAST(DATEADD(HOUR, 7, CURRENT_TIMESTAMP()) AS DATE) GROUP BY 1, 2, 3 ) , wh_cut_size_list AS ( SELECT parent_style FROM base_wh_data GROUP BY 1 HAVING COUNT(CASE WHEN (COALESCE(\"Available\",0) + COALESCE(\"Blocked\",0)) <= 1 THEN 1 END) >= (0.5 * COUNT(*)) AND COUNT(CASE WHEN (COALESCE(\"Available\",0) + COALESCE(\"Blocked\",0)) = 1 THEN 1 END) < COUNT(*) ) , warehouse AS ( SELECT b.sku_item AS sku_group, b.parent_style, b.\"Category Name\", b.\"Available\", b.\"Blocked\", b.\"Not Found\", b.\"Putaway Pending\", b.\"Putback Pending\", b.\"Bad Inventory\", b.\"Not Synced\", b.\"Stock Transfer\", CASE WHEN csl.parent_style IS NOT NULL THEN 1 ELSE 0 END AS is_wh_cut_size FROM base_wh_data b LEFT JOIN wh_cut_size_list csl ON b.parent_style = csl.parent_style ), offline_raw AS ( SELECT UPPER(TRIM(SKU_GROUP)) AS parent_style, SUM(INVENTORY) AS available_inv, SUM(COALESCE(XS_UNITS, 0)) AS total_xs, SUM(COALESCE(S_UNITS, 0)) AS total_s, SUM(COALESCE(M_UNITS, 0)) AS total_m, SUM(COALESCE(L_UNITS, 0)) AS total_l, SUM(COALESCE(XL_UNITS, 0)) AS total_xl, SUM(COALESCE(XXL_UNITS, 0)) AS total_xxl FROM snitch_db.maplemonk.offline_master GROUP BY 1 ), offline_cut_size_list AS ( SELECT parent_style, ( CASE WHEN total_xs <= 1 THEN 1 ELSE 0 END + CASE WHEN total_s <= 1 THEN 1 ELSE 0 END + CASE WHEN total_m <= 1 THEN 1 ELSE 0 END + CASE WHEN total_l <= 1 THEN 1 ELSE 0 END + CASE WHEN total_xl <= 1 THEN 1 ELSE 0 END + CASE WHEN total_xxl <= 1 THEN 1 ELSE 0 END ) AS broken_size_count FROM offline_raw ), offline_inv AS ( SELECT o.parent_style, o.available_inv, 0 AS jit_inv, CASE WHEN ocsl.broken_size_count >= 3 THEN 1 ELSE 0 END AS is_offline_cut_size FROM offline_raw o LEFT JOIN offline_cut_size_list ocsl ON o.parent_style = ocsl.parent_style ), cogs AS ( SELECT UPPER(TRIM(SKUGROUP)) AS parent_style_key, MAX(cost_price) AS cost_price FROM snitch_db.maplemonk.uc_final_item_master GROUP BY 1 ), sku_category AS ( SELECT DISTINCT TRIM(REGEXP_REPLACE(UPPER(TRIM(\"Item SkuCode\")), \'-[^-]*$\', \'\')) AS parent_style, \"Category Name\" AS category_name FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE \"Category Name\" IS NOT NULL ), wh_rollup AS ( SELECT a.\"Category Name\" AS category_name, SUM(a.\"Available\") AS qty_available, SUM(a.\"Blocked\") AS qty_blocked, SUM(a.\"Not Found\") AS qty_not_found, SUM(a.\"Bad Inventory\") AS qty_bad_inventory, SUM(a.\"Not Synced\") AS qty_not_synced, SUM(a.\"Putaway Pending\") AS qty_putaway_pending, SUM(a.\"Putback Pending\") AS qty_putback_pending, SUM(a.\"Stock Transfer\") AS qty_stock_transfer, SUM(a.\"Available\" * COALESCE(b.cost_price, 0)) AS available_cogs, SUM(a.\"Blocked\" * COALESCE(b.cost_price, 0)) AS blocked_cogs, SUM(a.\"Not Found\" * COALESCE(b.cost_price, 0)) AS not_found_cogs, SUM(a.\"Bad Inventory\" * COALESCE(b.cost_price, 0)) AS bad_inventory_cogs, SUM(a.\"Not Synced\" * COALESCE(b.cost_price, 0)) AS not_synced_cogs, SUM(a.\"Putaway Pending\" * COALESCE(b.cost_price, 0)) AS putaway_pending_cogs, SUM(a.\"Putback Pending\" * COALESCE(b.cost_price, 0)) AS putback_pending_cogs, SUM(a.\"Stock Transfer\" * COALESCE(b.cost_price, 0)) AS stock_transfer_cogs, SUM(CASE WHEN a.is_wh_cut_size = 1 THEN (a.\"Available\" + a.\"Blocked\") * COALESCE(b.cost_price, 0) ELSE 0 END) AS cut_size_wh_cogs FROM warehouse a LEFT JOIN cogs b ON a.parent_style = b.parent_style_key GROUP BY a.\"Category Name\" ), offline_rollup AS ( SELECT sc.category_name, SUM(oi.available_inv) AS qty_offline_available, SUM(oi.available_inv * COALESCE(c.cost_price, 0)) AS offline_available_cogs, SUM(oi.jit_inv) AS qty_jit, SUM(oi.jit_inv * COALESCE(c.cost_price, 0)) AS jit_cogs, SUM(CASE WHEN oi.is_offline_cut_size = 1 THEN oi.available_inv * COALESCE(c.cost_price, 0) ELSE 0 END) AS cut_size_offline_cogs FROM offline_inv oi LEFT JOIN cogs c ON oi.parent_style = c.parent_style_key LEFT JOIN sku_category sc ON oi.parent_style = sc.parent_style GROUP BY sc.category_name ), pre_calculation AS ( SELECT w.category_name as w_cat, o.category_name as o_cat, COALESCE(w.qty_available, 0) as qty_available, COALESCE(w.qty_blocked, 0) as qty_blocked, COALESCE(w.qty_not_found, 0) as qty_not_found, COALESCE(w.qty_bad_inventory, 0) as qty_bad_inventory, COALESCE(w.qty_not_synced, 0) as qty_not_synced, COALESCE(w.qty_putaway_pending, 0) as qty_putaway_pending, COALESCE(w.qty_putback_pending, 0) as qty_putback_pending, COALESCE(w.qty_stock_transfer, 0) as qty_stock_transfer, COALESCE(w.available_cogs, 0) as available_cogs, COALESCE(w.blocked_cogs, 0) as blocked_cogs, COALESCE(w.not_found_cogs, 0) as not_found_cogs, COALESCE(w.bad_inventory_cogs, 0) as bad_inventory_cogs, COALESCE(w.not_synced_cogs, 0) as not_synced_cogs, COALESCE(w.putaway_pending_cogs, 0) as putaway_pending_cogs, COALESCE(w.putback_pending_cogs, 0) as putback_pending_cogs, COALESCE(w.stock_transfer_cogs, 0) as stock_transfer_cogs, COALESCE(w.cut_size_wh_cogs, 0) as cut_size_wh_cogs, COALESCE(o.qty_offline_available, 0) as qty_offline_available, COALESCE(o.qty_jit, 0) as qty_jit, COALESCE(o.offline_available_cogs, 0) as offline_available_cogs, COALESCE(o.jit_cogs, 0) as jit_cogs, COALESCE(o.cut_size_offline_cogs, 0) as cut_size_offline_cogs, (COALESCE(w.available_cogs, 0) + COALESCE(w.blocked_cogs, 0)) AS \"TOTAL_COGS_Available_WH\", (COALESCE(w.not_found_cogs, 0) + COALESCE(w.bad_inventory_cogs, 0) + COALESCE(w.not_synced_cogs, 0) + COALESCE(w.putaway_pending_cogs, 0) + COALESCE(w.putback_pending_cogs, 0) + COALESCE(w.stock_transfer_cogs, 0)) AS \"Not_Sellable_COGS\" FROM wh_rollup w FULL OUTER JOIN offline_rollup o ON w.category_name = o.category_name ), mapped_data AS ( SELECT CASE WHEN COALESCE(w_cat, o_cat) IN (\'Accessories\', \'Default\', \'Co-Ords\', \'Boxers\', \'Inner Wear\', \'Night Suit & Pyjamas\', \'PYJAMAS\', \'Pyjamas\') THEN \'Others\' WHEN COALESCE(w_cat, o_cat) IN (\'Chinos\', \'Trouser\', \'Trousers\') THEN \'Trousers\' WHEN COALESCE(w_cat, o_cat) IN (\'Trackpants\', \'JOGGERS\', \'Joggers & Trackpants\') THEN \'Joggers & Trackpants\' WHEN COALESCE(w_cat, o_cat) IN (\'Shirt\', \'Shirts\') THEN \'Shirts\' ELSE CASE WHEN COALESCE(w_cat, o_cat) IN (\'Sweater\') THEN \'Sweaters\' WHEN COALESCE(w_cat, o_cat) = \'Footwear\' THEN \'Shoes\' WHEN COALESCE(w_cat, o_cat) = \'Jacket\' THEN \'Jackets\' ELSE COALESCE(w_cat, o_cat) END END AS \"New Cat\", \"TOTAL_COGS_Available_WH\", offline_available_cogs, cut_size_wh_cogs, cut_size_offline_cogs, \"Not_Sellable_COGS\", jit_cogs FROM pre_calculation ) SELECT \"New Cat\", SUM(\"TOTAL_COGS_Available_WH\") AS \"TOTAL_COGS_Available_WH\", SUM(offline_available_cogs) AS offline_available_cogs, SUM(\"TOTAL_COGS_Available_WH\" + offline_available_cogs) AS \"Available - WH + Store\", SUM(cut_size_wh_cogs) AS \"Cut Size COGS (WH)\", SUM(cut_size_offline_cogs) AS \"Cut Size COGS (Store)\", SUM(cut_size_wh_cogs + cut_size_offline_cogs) AS \"Total Cut Size COGS\", SUM(\"Not_Sellable_COGS\") AS \"Not_Sellable_COGS\", SUM(jit_cogs) AS jit_cogs, SUM( (\"TOTAL_COGS_Available_WH\" + offline_available_cogs) + \"Not_Sellable_COGS\" + jit_cogs ) AS total_cogs FROM mapped_data GROUP BY 1 ORDER BY CASE WHEN \"New Cat\" = \'Others\' THEN 1 ELSE 0 END, \"New Cat\" ASC;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            